const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const removeIcon=`<img class="lt-icon" src="${new URL('./icons/close.svg',import.meta.url)}" alt="">`;
const button=(text,action,primary=false,disabled=false)=>`<button type="button" class="ui-button ${primary?'ui-button--primary':'ui-button--tertiary'}" data-action="mgmt-${action}" ${disabled?'disabled':''}>${text}</button>`;
const tags=values=>values.length?`<div class="lt-tags">${values.map(word=>`<span class="ui-tag">${esc(word)}</span>`).join('')}</div>`:'<p class="lt-meta">无</p>';
const section=(label,content)=>`<section class="lt-section lt-stack"><h2 class="ui-section-title">${label}</h2>${content}</section>`;
const reviewSection=(label,key,content)=>`<details open class="lt-section" data-management-group="${key}"><summary>${label}</summary><div class="lt-stack">${content}</div></details>`;
const ranges=values=>values.map(range=>`${range.start}—${range.end}楼`).join('、');
function words(value) {return section('事件词',tags(value.eventWords))+section('细节词与简称',value.detailWords.length?value.detailWords.map(term=>`<div class="lt-stack"><span class="ui-tag">${esc(term.word)}</span>${term.aliases.length?`<p class="lt-meta">简称：${term.aliases.map(esc).join('、')}</p>`:''}</div>`).join(''):'<p class="lt-meta">无</p>');}
function facts(event) {return `<p class="lt-meta">${event.mode==='resident'?'常驻':'触发'} · ${esc(ranges(event.sources))}</p>${event.title?`<h2 class="ui-section-title">${esc(event.title)}</h2>`:''}${section('正文',`<p class="ui-reading lt-management-copy">${esc(event.body)}</p>`)}${section('时间与来源',`<p>${esc([event.startTime,event.endTime].filter(Boolean).join('—'))}</p><p class="lt-meta">${esc(ranges(event.sources))}</p>`)}${section('人物与地点',tags(event.people)+tags(event.places))}`;}
function field(label,key,value,textarea=false) {return `<label class="ui-field"><span class="ui-field__label">${label}</span>${textarea?`<textarea class="lt-textarea" data-management-field="${key}" rows="7">${esc(value)}</textarea>`:`<input class="ui-input" data-management-field="${key}" value="${esc(value)}">`}</label>`;}
export function managementParticipantTags(key,values) {return values.map((value,index)=>`<span class="ui-tag">${esc(value)}<button type="button" class="ui-icon-button ui-button--tertiary" data-management-remove="${key}" data-index="${index}" aria-label="删除${esc(value)}"><img class="lt-icon" src="${new URL('./icons/close.svg',import.meta.url)}" alt=""></button></span>`).join('');}
function participants(label,key,values) {return `<div class="lt-stack"><h3 class="ui-field__label">${label}</h3><div class="lt-tags" data-management-tags="${key}">${managementParticipantTags(key,values)}</div><div class="lt-entry"><input class="ui-input" data-management-entry="${key}" aria-label="添加${label}" placeholder="输入${label}"><button type="button" class="ui-button ui-button--tertiary" data-management-add="${key}" hidden>添加</button></div></div>`;}
function indexEditor(item,index,state){
 const terms=item.detailWords.map(term=>`<div class="lt-term" data-open="${state.openIndexTerm===term.id}" data-aliases="${!!term.aliasesText}"><div class="lt-term-head"><button type="button" class="ui-button ui-button--tertiary" data-index-term="${esc(term.id)}" aria-expanded="${state.openIndexTerm===term.id}">${esc(term.word)}</button><button type="button" class="ui-icon-button ui-button--tertiary" data-index-delete="${esc(term.id)}" aria-label="删除${esc(term.word)}">${removeIcon}</button></div>${state.openIndexTerm===term.id?`<div class="lt-term-fields"><label class="lt-term-field ui-field__label">细节词<input class="ui-input" data-index-field="word" data-term-id="${esc(term.id)}" value="${esc(term.word)}"></label><label class="lt-term-field ui-field__label">简称<input class="ui-input" data-index-field="aliasesText" data-term-id="${esc(term.id)}" value="${esc(term.aliasesText)}"></label></div>`:''}</div>`).join('');
 return `<section class="lt-section lt-stack" data-index-result="${index}" ${state.errorIndex===index?'data-invalid="true"':''}><h2 class="ui-section-title">${esc(state.events.find(event=>event.id===item.id)?.title||`记忆 ${index+1}`)}</h2>${state.errorIndex===index?`<p class="lt-error" role="alert">${esc(state.error)}</p>`:''}<div class="lt-stack"><h3 class="ui-field__label">事件词</h3><div class="lt-tags">${item.eventWords.map((word,position)=>`<span class="ui-tag">${esc(word)}<button type="button" class="ui-icon-button ui-button--tertiary" data-index-remove-event="${position}" aria-label="删除${esc(word)}">${removeIcon}</button></span>`).join('')}</div>${indexEntry('事件词','event',item.eventEntry)}</div><div class="lt-stack"><h3 class="ui-field__label">细节词与简称</h3><div class="lt-terms">${terms}</div>${indexEntry('细节词','detail',item.detailEntry)}</div><details data-management-group="original-${index}"><summary>查看原关键词</summary><div class="lt-stack">${words(state.candidate.comparisons.find(compare=>compare.id===item.id).before)}</div></details></section>`;
}
function indexEntry(label,key,value=''){return `<div class="lt-entry"><input class="ui-input" data-index-entry="${key}" value="${esc(value)}" aria-label="添加${label}" placeholder="输入${label}"><button type="button" class="ui-button ui-button--tertiary" data-index-add="${key}" ${value.trim()?'':'hidden'}>添加</button></div>`;}
export function managementView(state) {
 const title=state.kind==='keywords'?'重建关键词与检索简称':'合并记忆';let content='',actions='';
 if(state.status==='preflight') {
  if(state.kind==='keywords'){content=state.error?'':'<p role="status">正在发起重建…</p>';}
  else {content=`<p>合并选中的 ${state.ids.length} 条记忆</p>`+section('正文来源',`<div class="lt-stack">${button('根据聊天原文融合','original',false,state.busy||!state.originalAvailable)}${!state.originalAvailable?'<p class="lt-meta">当前没有可确认的原文来源</p>':''}${button('根据记忆内容融合','memories',true,state.busy)}</div>`);}
 } else if(state.outcome==='unconfirmed') {content='<p role="alert">保存结果待确认，可能已经写入。请重新读取实际结果。</p>';actions=button('重新读取','recover',true,state.busy);}
 else if(state.status==='stale') {content='<p role="status">来源或聊天目标已变化，请返回后重新发起。</p>';}
 else if(state.status==='cancelled') {content='<p role="status">任务已取消</p>';}
 else if(state.status==='succeeded') {content='<p role="status">已完成，正在读取实际结果</p>';actions=button('重新读取','recover',true,state.busy);}
 else if(state.reviewPending) {
  const fields=state.fields,candidate=state.candidate;
  content=`<form class="lt-editor lt-management-body" novalidate>${candidate.coherenceWarning?`<p class="lt-management-warning" role="status">${esc(candidate.coherenceWarning)}</p>`:''}${section('基本信息',`<p class="lt-meta">${state.events.every(event=>event.mode==='resident')?'常驻':'触发'} · ${candidate.sourceCount} 条来源</p>${field('标题','title',fields.title)}`)}${reviewSection('正文','body',field('正文','body',fields.body,true))}${reviewSection('时间与来源','time',`<div class="lt-range">${field('故事时间起点','startTime',fields.startTime)}<span>—</span>${field('故事时间终点','endTime',fields.endTime)}</div><p class="lt-meta">${esc(ranges(candidate.ranges))}</p>`)}${reviewSection('人物与地点','participants',participants('人物','people',fields.people)+participants('地点','places',fields.places))}</form>`;
  actions=button('取消任务','cancel')+button('生成关键词与简称','review',true);
 } else if(state.status==='awaiting-user' || state.status==='failed' && state.hasCandidate) {
  const candidate=state.candidate;
  if(candidate.kind==='keywords')content=state.indexes.map((item,index)=>indexEditor(item,index,state)).join('');
  else content=`<p class="lt-meta">合并 ${candidate.sourceCount} 条记忆 · ${esc(ranges(candidate.ranges))}</p>${candidate.coherenceWarning?`<p class="lt-management-warning" role="status">${esc(candidate.coherenceWarning)}</p>`:''}${facts(candidate.event)}${words(candidate.event)}`;
  if(state.status==='failed')content='<p role="alert">保存未完成，审核候选已保留。可再次确认或取消。</p>'+content;
  actions=(candidate.kind==='keywords'?'':button('取消任务','cancel'))+button(candidate.kind==='keywords'?'保存重建结果':'确认合并','confirm',true,state.busy);
 } else if(state.status==='failed') {content='<p role="alert">生成未完成，请检查 API 设置或重新生成。正式记忆未提交。</p>'+button('前往 API 设置','settings');actions=button('取消任务','cancel')+button('重新生成','retry',true,state.busy);}
 else {content=`<p role="status">${state.status==='committing'?'正在保存…':state.stage==='merge-indexes'?'正在生成关键词与简称…':state.kind==='keywords'?`正在重建，共 ${state.ids.length} 条`:'正在融合正文…'}</p>`;actions=state.status==='committing'?'':button('取消任务','cancel');}
 return {title,content:`<div class="lt-management lt-stack">${state.error?`<p class="lt-error" role="alert">${esc(state.error)}</p>`:''}${content}${state.status==='preflight'&&state.error?button('前往 API 设置','settings'):''}</div>`,actions:`<div class="lt-management-actions">${actions}</div>`};
}
